export function buildSeed(nowMs: number, total = 500): Testimony[] {
  return Array.from({ length: total }, (_, i) => {
    const s = SEED[i % SEED.length];
    const round = Math.floor(i / SEED.length); // 0 for the first 95, 1 for the next, ...
    return {
      id: `seed-${String(i + 1).padStart(3, "0")}`,
      name: s.name,
      countryCode: s.countryCode,
      text: s.text,
      amens: s.amens,
      createdAt: new Date(nowMs - (s.minutesAgo + round * 2000) * 60_000).toISOString(),
    };
  });
}

 